// Prints a value the way the examples write it
static void Dump<T>(T value)
{
    Console.WriteLine(Show(value));
    static string Show(object? value) => value switch
    {
        null      => "null",
        bool b    => b ? "true" : "false",
        string s  => $"\"{s}\"",
        char c    => $"'{c}'",
        double d  => d.ToString(System.Globalization.CultureInfo.InvariantCulture),
        decimal m => m.ToString(System.Globalization.CultureInfo.InvariantCulture),
        Delegate  => "<function>",
        System.Collections.IEnumerable e when value.GetType().Namespace?.StartsWith("System") == true
                  => $"[{string.Join(", ", e.Cast<object?>().Select(Show))}]",
        _         => value.ToString() ?? "null"
    };
}

first-class-function:
// Stored in a variable
Func<int, int> square = x => x * x;

// Stored in a collection
var ops = new Dictionary<string, Func<int, int, int>>
{
    ["+"] = (a, b) => a + b,
    ["*"] = (a, b) => a * b,
};

// Passed in, and returned
Func<int, int> Twice(Func<int, int> f) => x => f(f(x));

var twelve = ops["*"](3, 4); Dump(twelve); // => 12
var eightyOne = Twice(square)(3); Dump(eightyOne); // => 81

int Increment(int x) => x + 1;

var inc = Increment;          // a method group converted to Func<int, int>
Func<double, double> abs = Math.Abs; // Math.Abs is overloaded, so the type is needed

var three = inc(2); Dump(three); // => 3
var two = abs(-2.0); Dump(two); // => 2

