{
    // Continues program with data
}

async Task ReadAndContinue(string path)
{
    try
    {
        var response = await File.ReadAllTextAsync(path);
        // Everything after the `await` is the continuation:
        ContinueProgramWith(response);
    }
    catch (IOException)
    {
        // handle error
    }
}

