declarative-programming:
var numbers = Seq(1, 2, 3, 4, 5, 6);

// Imperative: how to build the result, one mutation at a time
var squares = new List<int>();
foreach (var n in numbers)
{
    if (n % 2 == 0)
        squares.Add(n * n);
}
var imperative = squares; Dump(imperative); // => [4, 16, 36]

// Declarative: what the result is
Dump(numbers.Filter(n => n % 2 == 0).Map(n => n * n)); // => [4, 16, 36]

// The same with LINQ query syntax
var evensSquared = from n in numbers where n % 2 == 0 select n * n; Dump(evensSquared); // => [4, 16, 36]

