laws:
Func<int, Option<int>> half = x => x % 2 == 0 ? Some(x / 2) : None;
Func<int, Option<int>> dec  = x => x > 0 ? Some(x - 1) : None;
Func<int, int> inc = x => x + 1;
Func<int, int> dbl = x => x * 2;
var m = Some(8);

// Functor: identity and composition
var fId   = m.Map(x => x) == m; Dump(fId); // => true
var fComp = m.Map(x => dbl(inc(x))) == m.Map(inc).Map(dbl); Dump(fComp); // => true

// Monad: left identity, right identity and associativity
var leftId  = Some(8).Bind(half) == half(8); Dump(leftId); // => true
var rightId = m.Bind(x => Some(x)) == m; Dump(rightId); // => true
var assoc   = m.Bind(half).Bind(dec) == m.Bind(x => half(x).Bind(dec)); Dump(assoc); // => true

// Monoid: Seq with concatenation and the empty Seq
var xs = Seq(1, 2);
var mId    = xs + Seq<int>() == xs && Seq<int>() + xs == xs; Dump(mId); // => true
var mAssoc = (xs + Seq(3)) + Seq(4) == xs + (Seq(3) + Seq(4)); Dump(mAssoc); // => true

var lawful = new BadMax(-5).Combine(BadMax.Empty) == new BadMax(-5); Dump(lawful); // => false

// So folding a list of negative numbers invents a maximum that isn't in the list
Dump(Monoid.combine(Seq(new BadMax(-5), new BadMax(-3)))); // => BadMax { Value = 0 }

