kleisli-category:
Func<A, Option<C>> Then<A, B, C>(Func<A, Option<B>> f, Func<B, Option<C>> g) =>
    a => f(a).Bind(g);

Option<A> Id<A>(A a) => Some(a);

Func<string, Option<int>> parse = s => parseInt(s);
Func<int, Option<int>> positive = n => n > 0 ? Some(n) : None;
Func<int, Option<int>> halve = n => n % 2 == 0 ? Some(n / 2) : None;

var inputs = Seq("8", "-8", "x", "3");

// Identity: Id on either side changes nothing
var plain   = inputs.Map(parse); Dump(plain); // => [Some(8), Some(-8), None, Some(3)]
var idLeft  = inputs.Map(Then<string, string, int>(Id, parse)); Dump(idLeft); // => [Some(8), Some(-8), None, Some(3)]
var idRight = inputs.Map(Then<string, int, int>(parse, Id)); Dump(idRight); // => [Some(8), Some(-8), None, Some(3)]

// Associativity: the grouping doesn't matter
var grouped1 = inputs.Map(Then(Then(parse, positive), halve)); Dump(grouped1); // => [Some(4), None, None, None]
var grouped2 = inputs.Map(Then(parse, Then(positive, halve))); Dump(grouped2); // => [Some(4), None, None, None]

