Cont<R, string> Classify<R>(int n) =>
    Cont.CallCC<R, string, Unit>(exit =>
        from _ in n < 0 ? exit("negative") : Cont.Pure<R, Unit>(unit)
        from s in Cont.Pure<R, string>(n % 2 == 0 ? "even" : "odd")
        select s);

