// Promap :: (A2 -> A) -> (B -> B2) -> Func<A, B> -> Func<A2, B2>
Func<A2, B2> Promap<A, B, A2, B2>(
    Func<A, B> f, Func<A2, A> pre, Func<B, B2> post) =>
    x => post(f(pre(x)));

