// example 3: repeat function N times
// times :: int -> (int -> ()) -> ()
void Times(int n, Action<int> f)
{
    if (n == 0) return;
    f(n);
    Times(n - 1, f);
}
Times(3, Console.WriteLine);
// 3
// 2
// 1
// Times(-1, Console.WriteLine);  StackOverflowException

